INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Ang Bagong Pamilya ni Ponching', 'Ang Bagong Pamilya ni Ponching', 'ang-bagong-pamilya-ni-ponching-2016', 'Ponching, a naïve and religious text scammer, accidentally convinces a wealthy family that he is the estranged son of their deceased relative and heir to a large inheritance. Encouraged by his best friend Elmerson, he becomes increasingly involved with the family, but as genuine bonds form, Ponching struggles between confessing the truth and continuing the lie for the money.', '2016-01-01', 2016, 'assets/ponching.jpg', 'https://letterboxd.com/film/ang-bagong-pamilya-ni-ponching/', '{"cinemalaya","indie","drama","comedy"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
