INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('I America', 'I America', 'i-america-2016', 'Erica Berry, an Amerasian woman from Olongapo, reconnects with her American father after the U.S. Navy’s departure leaves many Filipino children fatherless. When she discovers that her birth certificate carries a different name, Erica begins questioning her identity and her father’s connection to her. Her search for the truth ultimately leads her to a deeper understanding of family and belonging.', '2016-01-01', 2016, 'assets/america.jpg', 'https://letterboxd.com/film/i-america/', '{"cinemalaya","indie","comedy","drama"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
