INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Hari ng Tondo', 'Hari ng Tondo', 'hari-ng-tondo-2014', 'Ricardo Villena loses his fortune just as his granddaughter Anna’s wedding falls apart and his grandson Ricky struggles to finish college. Hoping to toughen them up, Ricardo brings them from their sheltered life in Forbes Park to his rundown tenement in Tondo, where they encounter people and realities far removed from their privileged upbringing.', '2014-01-01', 2014, 'assets/hari.jpg', 'https://letterboxd.com/film/where-i-am-king/', '{"cinemalaya","indie","drama","family","comedy"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
