INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('1st Ko Si 3rd', '1st Ko Si 3rd', '1st-ko-si-3rd-2014', 'On her first day of retirement, 65-year-old Cory struggles to adjust to a quiet life with her husband until she unexpectedly reunites with Third, her first love. When Third asks her out, Cory finally gets the chance to fulfill the first date they never had and confront the feelings she has kept in her unsent love letters.', '2014-01-01', 2014, 'assets/1st.jpg', 'https://letterboxd.com/film/1st-ko-si-3rd/', '{"cinemalaya","indie","romance","drama","comedy"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
